<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';
import Icon from './Icon.vue';
import {api,isPublicDemo} from '../auth.js';
import {assetUrl} from '../urls.js';
const emit=defineEmits(['login']);
const role=ref('teacher'),username=ref(''),password=ref(''),show=ref(false),remember=ref(true),captcha=ref(''),challenge=ref(null),loading=ref(false),error=ref(''),help=ref(false),date=ref(new Date());let interval;
async function refresh(){try{challenge.value=await api('/api/auth/captcha');captcha.value='';}catch{error.value=isPublicDemo?'验证码加载失败，请刷新页面重试。':'本地登录服务未连接，请启动项目开发服务。';}}
async function login(demo=false){if(loading.value)return;if(!demo&&(!username.value||!password.value||!captcha.value)){error.value='请填写账号、密码和验证码';return;}loading.value=true;error.value='';try{const result=await api('/api/auth/login',{username:demo?role.value:username.value,password:demo?'Campus@2026':password.value,role:role.value,remember:remember.value,captcha:captcha.value,captchaId:challenge.value?.id,demo});emit('login',result.user);}catch(e){error.value=e.message;await refresh();}finally{loading.value=false;}}
onMounted(()=>{refresh();interval=setInterval(()=>date.value=new Date(),1000);});onBeforeUnmount(()=>clearInterval(interval));
</script>
<template><main class="login-page"><div class="login-campus-background" role="img" aria-label="校园夜景及宿舍数字孪生概念背景"></div>
 <header class="login-header"><div class="login-university"><img :src="assetUrl('/assets/login-logo.png')" alt="校园徽标"><div><b>XX 大学</b><span>智慧校园 · 平安校园</span></div></div><div class="login-date"><span>{{date.toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})}}　{{date.toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'})}}</span><small>厚德　博学　求是　创新</small></div><div class="login-title"><h1>校园消防数字孪生应急疏散决策系统</h1><p>Campus Fire Digital Twin Emergency Evacuation Decision System</p></div></header>
 <div class="login-metrics"><div><Icon name="fire"/><span>火烟仿真</span><b>软件模型</b><small>可导入 FDS 场数据</small></div><div><Icon name="speed"/><span>建筑尺度</span><b>48 × 18 <small>m</small></b><small>参数化尺寸假设</small></div><div><Icon name="walk"/><span>演练人数</span><b>286 <small>人</small></b><small>六层宿舍虚拟学员</small></div></div>
 <div class="campus-location dorm-location"><Icon name="pin"/>学生宿舍</div><div class="campus-location library-location"><Icon name="pin"/>图书馆</div><div class="campus-location teaching-location"><Icon name="pin"/>教学楼</div><div class="campus-fire-tag"><Icon name="alert"/><div><b>宿舍楼</b><small>火灾演练场景</small></div></div>
 <section class="login-card"><h2>系统登录</h2><p class="login-welcome">欢迎登录校园应急数字孪生平台</p><form @submit.prevent="login(false)"><label class="login-field"><Icon name="person"/><input v-model="username" autocomplete="username" placeholder="账号 / 工号 / 学号" aria-label="账号 / 工号 / 学号" maxlength="64"></label><label class="login-field"><Icon name="lock"/><input v-model="password" :type="show?'text':'password'" autocomplete="current-password" placeholder="请输入密码" aria-label="密码" maxlength="256"><button type="button" class="password-eye" @click="show=!show" :aria-label="show?'隐藏密码':'显示密码'"><Icon :name="show?'eye':'eyeoff'"/></button></label><div class="captcha-row"><label class="login-field"><Icon name="shieldOutline"/><input v-model="captcha" placeholder="验证码" aria-label="验证码" maxlength="4" autocomplete="off"></label><img v-if="challenge" :src="challenge.image" alt="图形验证码"><button type="button" class="captcha-refresh" @click="refresh" aria-label="刷新验证码"><Icon name="refresh"/></button></div><div class="login-options"><label><input type="checkbox" v-model="remember">记住我</label><button type="button" @click="help=true">忘记密码?</button></div><p v-if="error" class="login-error" role="alert">{{error}}</p><button type="submit" class="login-submit" :disabled="loading">{{loading?'正在登录…':'登录系统'}}<Icon name="forward"/></button></form><div class="login-roles"><button v-for="[key,label] in [['teacher','教师入口'],['student','学生入口'],['admin','管理员入口']]" type="button" :class="{selected:role===key}" @click="role=key;error=''">{{label}}</button></div><div class="login-demo"><span>{{isPublicDemo?`演示账号 ${role} · 密码 Campus@2026`:'本地演示账号 · 无需传感器'}}</span><button @click="login(true)" :disabled="loading">使用{{{teacher:'教师',student:'学生',admin:'管理员'}[role]}}演示账号 <Icon name="next"/></button></div></section>
 <div class="login-features"><button v-for="feature in [{icon:'building',name:'真实建筑孪生',detail:'IFC语义模型 · GLB三维场景'},{icon:'fire',name:'火烟仿真分析',detail:'软件模拟 · 外部场数据回放'},{icon:'walk',name:'动态疏散路径',detail:'风险与拥堵协同规划'},{icon:'chart',name:'应急指挥大屏',detail:'统一状态驱动多端联动'}]" @click="help=true"><Icon :name="feature.icon"/><span><b>{{feature.name}}</b><small>{{feature.detail}}</small></span><Icon name="next"/></button></div>
 <footer class="login-footer"><span><Icon name="desktop"/>建议使用 Chrome / Edge 浏览器访问</span><span>© 2026 XX大学安全管理中心</span></footer>
 <div v-if="help" class="modal-backdrop" @click.self="help=false"><section class="modal" role="dialog" aria-modal="true" aria-label="登录帮助"><div class="modal-heading"><h2>{{isPublicDemo?'公开演示说明':'本地平台登录帮助'}}</h2><button @click="help=false" aria-label="关闭帮助"><Icon name="close"/></button></div><p>教师账号：teacher<br>学生账号：student<br>管理员账号：admin<br>演示密码：Campus@2026</p><p>选择对应入口后可使用演示账号按钮直接体验。常规登录需要输入图形验证码。</p><p v-if="!isPublicDemo">本地账户由SQLite保存，密码经过scrypt哈希，登录会话通过HttpOnly Cookie维护。尚未对接学校统一身份认证或邮件找回。</p><p v-if="isPublicDemo">这是独立的软件演示。账号、密码和验证码在当前浏览器校验，仅用于体验，不代表真实身份或服务器权限。记录保存在本机浏览器，可导出；没有服务器账户、实时传感器或多人网络同步。</p><p>背景为参考图衍生的概念视觉。系统内的宿舍使用米制3D模型，尺寸为参数化假设。</p><button class="primary full-width" @click="help=false">返回登录</button></section></div>
</main></template>

